import React, { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import { cn } from "@/lib/utils";
import axiosInstance, { contactsApi, transactionsApi } from "../../utility/axiosInstance";
import { API_URL } from "../../utility/constants";
import {
  DropdownMenu,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuItem,
} from "@/components/ui/dropdown-menu";

import Home from "./Home";
import Groups from "./Groups";
import Friends from "./Friends";
import History from "./History";
import PaymentMethods from "./PaymentMethods";
import Notifications from "./Notifications";
import ProfileImageCapture from "./ProfileImageCapture";

import {
  LogOut,
  Search,
  Bell,
  ChevronDown,
  User,
  LayoutDashboard,
  History as HistoryIcon,
  UsersRound,
} from "lucide-react";

const DEV_BYPASS_AUTH = process.env.REACT_APP_BYPASS_AUTH === "true";

// Top-bar search results — static services plus whatever friends match.
const SEARCH_SERVICES = [
  { id: "send", label: "Send Money", section: "send" },
  { id: "add-money", label: "Add Money", section: "add-money" },
  { id: "withdraw", label: "Withdraw", section: "withdraw" },
  { id: "groups", label: "Groups", section: "groups" },
];

// Shared class strings for the user-menu dropdown items (Account/Update
// Photo share one style, Log out layers destructive coloring on top).
const dropdownItemClass =
  "flex items-center gap-2 px-4 py-3 text-foreground text-[0.9rem] font-medium rounded-sm cursor-pointer transition-all duration-[250ms] ease-in-out hover:bg-[var(--gold-pale)] hover:text-gold focus:bg-[var(--gold-pale)] focus:text-gold";
const dropdownItemLogoutClass = cn(
  dropdownItemClass,
  "mt-1 text-destructive hover:bg-destructive/[0.08] hover:text-destructive focus:bg-destructive/[0.08] focus:text-destructive",
);
const searchResultItemClass =
  "flex items-center justify-between gap-2 w-full bg-transparent border-none text-foreground text-[0.85rem] font-medium text-left py-[0.6rem] px-[0.8rem] rounded-sm cursor-pointer transition-all duration-[250ms] ease-in-out hover:bg-[var(--gold-pale)] hover:text-gold";

/* ─── Footer — copied from App.js's landing-page Footer ─── */
function Footer() {
  return (
    <footer className="border-t-[0.5px] border-t-border">
      <div className="flex items-center justify-between max-w-[1280px] mx-auto py-5 px-6 flex-wrap gap-4 max-[768px]:flex-col max-[768px]:items-start max-[768px]:p-5">
        <div className="flex items-center gap-2.5">
          <img
            src="/images/payzarc.png"
            className="h-[2.2rem] w-auto block"
            alt="Payzarc-logo"
          />
          <p className="text-xs text-[var(--muted)]">
            Your trusted cross-border financial partner.
          </p>
        </div>
        <div className="flex flex-col gap-[3px] text-center max-[768px]:text-left">
          <a
            href="mailto:info.e@payzarc.com"
            className="text-xs font-semibold text-gold no-underline"
          >
            info.e@payzarc.com
          </a>
          <span className="text-[11px] text-[var(--muted)]">+1 (713) 822-8593</span>
          <span className="text-[11px] text-[var(--muted)]">
            Kew Gardens Dr Houston Tx, USA
          </span>
        </div>
      </div>
    </footer>
  );
}

export default function Dashboard() {
  const [activePage, setActivePage] = useState("home");
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [isUserMenuOpen, setIsUserMenuOpen] = useState(false);
  const [selectedTransaction, setSelectedTransaction] = useState(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [friends, setFriends] = useState([]);
  // A one-off "go here" instruction for Home.js, set when a top-bar search
  // result is picked. Timestamped so picking the same result twice in a row
  // still re-triggers Home's effect.
  const [navigateRequest, setNavigateRequest] = useState(null);
  const [notifications, setNotifications] = useState([]);
  const [hideTopBar, setHideTopBar] = useState(false);

  const navigate = useNavigate();
  const dropdownRef = useRef(null);
  const searchRef = useRef(null);
  const lastScrollY = useRef(0);

  useEffect(() => {
    const handleClick = (e) => {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target)) {
        setIsUserMenuOpen(false);
      }
      if (searchRef.current && !searchRef.current.contains(e.target)) {
        setSearchTerm("");
      }
    };
    document.addEventListener("mousedown", handleClick);
    return () => document.removeEventListener("mousedown", handleClick);
  }, []);

  // Hides the topbar while scrolling down (past its own height, so it
  // doesn't flicker right at the top) and brings it back the moment the
  // user scrolls up at all — the standard "proper" hide-on-scroll pattern.
  useEffect(() => {
    const handleScroll = () => {
      const currentY = window.scrollY;
      const scrolledPastBar = currentY > 96;
      const scrollingDown = currentY > lastScrollY.current;
      setHideTopBar(scrolledPastBar && scrollingDown);
      lastScrollY.current = currentY;
    };
    window.addEventListener("scroll", handleScroll, { passive: true });
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  useEffect(() => {
    contactsApi
      .get("/api/favorites/all/")
      .then((res) => {
        const raw = res.data;
        const list = Array.isArray(raw)
          ? raw
          : raw?.favourites || raw?.results || raw?.data || [];
        setFriends(Array.isArray(list) ? list : []);
      })
      .catch(() => setFriends([]));
  }, []);

  useEffect(() => {
    transactionsApi
      .get("/api/notifications/")
      .then((res) => setNotifications(Array.isArray(res.data) ? res.data : []))
      .catch(() => setNotifications([]));
  }, []);

  useEffect(() => {
    const fetchUser = async () => {
      try {
        const response = await axiosInstance.get("/api/dashboard");
        const userData = response.data;
        setUser(userData);
        localStorage.setItem("user", JSON.stringify(userData));
      } catch (err) {
        console.error("Failed to load dashboard:", err);
        if (DEV_BYPASS_AUTH) {
          setUser((u) => u || {});
        } else {
          localStorage.removeItem("accessToken");
          localStorage.removeItem("user");
          navigate("/components/member/login");
        }
      } finally {
        setLoading(false);
      }
    };

    const saved = localStorage.getItem("user");
    if (saved) setUser(JSON.parse(saved));
    fetchUser();
  }, [navigate]);

  const handleLogout = async () => {
    try {
      await axiosInstance.post("/api/logout");
    } catch (err) {
      console.warn("Logout API failed:", err);
    } finally {
      localStorage.removeItem("accessToken");
      localStorage.removeItem("user");
      navigate("/components/member/login");
    }
  };

  const handleNavClick = (page) => {
    setActivePage(page);
    setIsUserMenuOpen(false);
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  const unreadNotificationCount = notifications.filter((n) => !n.read).length;

  const searchTermLower = searchTerm.trim().toLowerCase();
  const matchedServices = searchTermLower
    ? SEARCH_SERVICES.filter((s) => s.label.toLowerCase().includes(searchTermLower))
    : [];
  const matchedFriends = searchTermLower
    ? friends
        .filter((f) => {
          const name = (f.display_name || f.name || "").toLowerCase();
          const phone = (f.phone || "").toLowerCase();
          const email = (f.email || "").toLowerCase();
          return (
            name.includes(searchTermLower) ||
            phone.includes(searchTermLower) ||
            email.includes(searchTermLower)
          );
        })
        .slice(0, 5)
    : [];

  const goToSection = (section) => {
    handleNavClick("home");
    setNavigateRequest({ id: Date.now(), section });
    setSearchTerm("");
  };

  const goToFriend = (fav) => {
    handleNavClick("home");
    setNavigateRequest({ id: Date.now(), section: "send", recipient: fav });
    setSearchTerm("");
  };

  const handleImageCapture = () => {
    setActivePage("profileImageCapture");
    setIsUserMenuOpen(false);
  };

  const refreshUser = () => {
    const saved = localStorage.getItem("user");
    if (saved) setUser(JSON.parse(saved));
    axiosInstance
      .get("/api/dashboard")
      .then((res) => {
        setUser(res.data);
        localStorage.setItem("user", JSON.stringify(res.data));
      })
      .catch(() => {});
  };

  const displayName =
    `${user?.firstname || ""} ${user?.surname || ""}`.trim() ||
    user?.username ||
    "User";

  const renderContent = () => {
    switch (activePage) {
      case "home":
        return (
          <Home
            onPageChange={handleNavClick}
            user={user}
            navigateRequest={navigateRequest}
          />
        );
      case "groups":
        return (
          <>
            <Friends />
            <Groups />
          </>
        );
      case "history":
        return (
          <History
            selectedTransaction={selectedTransaction}
            openDetailsPopup={(tx) => setSelectedTransaction(tx)}
            closeDetailsPopup={() => setSelectedTransaction(null)}
          />
        );
      case "account":
        return (
          <PaymentMethods user={user} onBack={() => setActivePage("home")} />
        );
      case "notifications":
        return <Notifications onBack={() => setActivePage("home")} />;
      case "profileImageCapture":
        return (
          <ProfileImageCapture
            user={user}
            onRefreshUser={refreshUser}
            onBack={() => setActivePage("account")}
          />
        );
      case "add-money":
      case "withdraw":
      case "send":
        return (
          <div className="text-center py-24 px-4 bg-card rounded-lg border border-border max-w-[800px] mx-auto">
            <h2 className="text-gold mb-4">
              {activePage.replace("-", " ").toUpperCase()}
            </h2>
            <p className="text-[var(--muted)] mb-8">This feature is coming soon.</p>
            <button
              onClick={() => setActivePage("home")}
              className="py-[0.8rem] px-8 bg-gold border-none rounded-[3rem] font-bold cursor-pointer transition-all duration-[250ms] ease-in-out hover:bg-gold-dark hover:-translate-y-0.5"
            >
              Back to Overview
            </button>
          </div>
        );
      default:
        return (
          <Home
            onPageChange={handleNavClick}
            user={user}
            navigateRequest={navigateRequest}
          />
        );
    }
  };

  if (loading)
    return (
      <div className="flex flex-col items-center justify-center h-screen bg-background text-[var(--muted)]">
        <div className="w-12 h-12 border-4 border-secondary border-t-gold rounded-full animate-spin"></div>
        <p>Loading Payzarc Dashboard...</p>
      </div>
    );
  if (!user) return null;

  return (
    <div className="bg-[#0602145f] bg-fixed min-[900px]:[zoom:clamp(0.72,calc(100vw/1920),1.2)]">
      <div className="relative flex w-full min-h-screen text-foreground overflow-x-hidden bg-[radial-gradient(rgba(255,242,0,0.067),var(--bg))] bg-fixed">
        <div className="fixed rounded-full border border-[rgba(236,201,75,0.07)] pointer-events-none w-[600px] h-[600px] -top-[160px] left-1/2 -translate-x-1/2" />
        <div className="fixed rounded-full border border-[rgba(236,201,75,0.07)] pointer-events-none w-[380px] h-[380px] -top-[60px] left-1/2 -translate-x-1/2" />
        <div className="flex-1 flex flex-col min-w-0 min-h-screen">
          {/* Simplified Top Bar */}
          <header
            className={cn(
              "h-20 bg-[rgba(13,17,23,0.85)] backdrop-blur-[20px] border-b border-border flex items-center justify-center sticky top-0 z-[100] w-full shadow-[0_1px_0_rgba(255,255,255,0.03)] transition-transform duration-300 ease-in-out",
              hideTopBar && "-translate-y-full",
            )}
          >
            <div className="grid grid-cols-[1fr_auto_1fr] items-center gap-8 w-full max-w-[1280px] px-6 max-[768px]:px-4">
              <div className="flex items-center justify-self-start">
                <div
                  className="cursor-pointer shrink-0"
                  onClick={() => handleNavClick("home")}
                  role="button"
                >
                  <img
                    src="/images/payzarc.png"
                    alt="Payzarc"
                    className="h-[2.2rem] w-auto block"
                  />
                </div>
              </div>

              <div
                className="relative flex items-center w-[280px] justify-self-center max-[768px]:hidden"
                ref={searchRef}
              >
                <Search
                  className="absolute left-3.5 text-[var(--muted)] pointer-events-none"
                  size={18}
                />
                <input
                  type="search"
                  placeholder="Search services or friends..."
                  className="w-full bg-white/5 border border-border rounded-full py-[0.55rem] pr-4 pl-[2.8rem] text-foreground text-[0.85rem] outline-none transition-all duration-[250ms] ease-in-out focus:border-[var(--gold-border)] focus:w-[320px]"
                  aria-label="Search"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />

                {searchTermLower && (
                  <div
                    className="absolute top-[calc(100%+8px)] left-0 w-full min-w-[260px] bg-secondary border border-input rounded-md shadow-[0_25px_50px_rgba(0,0,0,0.6)] p-[0.6rem] z-[200] flex flex-col gap-[0.4rem] animate-popup-in"
                    role="listbox"
                  >
                    {matchedServices.length === 0 &&
                    matchedFriends.length === 0 ? (
                      <span className="py-[0.6rem] px-[0.8rem] text-[0.85rem] text-[var(--muted)]">
                        No matches for "{searchTerm}"
                      </span>
                    ) : (
                      <>
                        {matchedServices.length > 0 && (
                          <div className="flex flex-col">
                            <span className="px-[0.8rem] pt-[0.4rem] pb-[0.2rem] text-[0.7rem] font-bold text-[var(--muted)] uppercase tracking-[0.06em]">
                              Services
                            </span>
                            {matchedServices.map((s) => (
                              <button
                                key={s.id}
                                type="button"
                                className={searchResultItemClass}
                                onClick={() => goToSection(s.section)}
                              >
                                {s.label}
                              </button>
                            ))}
                          </div>
                        )}
                        {matchedFriends.length > 0 && (
                          <div className="flex flex-col">
                            <span className="px-[0.8rem] pt-[0.4rem] pb-[0.2rem] text-[0.7rem] font-bold text-[var(--muted)] uppercase tracking-[0.06em]">
                              Friends
                            </span>
                            {matchedFriends.map((f) => (
                              <button
                                key={f.id}
                                type="button"
                                className={searchResultItemClass}
                                onClick={() => goToFriend(f)}
                              >
                                {f.display_name || f.name}
                                <span className="text-[var(--muted)] text-[0.78rem] font-normal">
                                  {f.phone || f.email}
                                </span>
                              </button>
                            ))}
                          </div>
                        )}
                      </>
                    )}
                  </div>
                )}
              </div>

              <div className="flex items-center justify-self-end">
                <div className="flex items-center gap-5">
                  <div
                    className="relative cursor-pointer text-[var(--muted)] w-10 h-10 rounded-full bg-white/[0.03] border border-border flex items-center justify-center transition-all duration-[250ms] ease-in-out hover:bg-white/[0.08] hover:text-foreground"
                    aria-label="Notifications"
                    role="button"
                    tabIndex={0}
                    onClick={() => handleNavClick("notifications")}
                  >
                    <Bell size={22} />
                    {unreadNotificationCount > 0 && (
                      <span className="absolute -top-0.5 -right-0.5 bg-gold text-black text-[9px] font-bold w-4 h-4 flex items-center justify-center rounded-full border-2 border-background">
                        {unreadNotificationCount}
                      </span>
                    )}
                  </div>

                  <DropdownMenu open={isUserMenuOpen} onOpenChange={setIsUserMenuOpen}>
                    <DropdownMenuTrigger asChild>
                      <div
                        className="group flex items-center gap-2 cursor-pointer"
                        ref={dropdownRef}
                      >
                        <div className="relative w-10 h-10 rounded-xl border-2 border-[var(--gold-border)] transition-colors duration-[250ms] ease-in-out group-hover:border-gold">
                          <img
                            src={
                              user.profileImageUrl
                                ? `${API_URL}${user.profileImageUrl}`
                                : "/images/default-user.png"
                            }
                            alt={`${displayName} avatar`}
                            className="w-full h-full rounded-[10px] object-cover transition-transform duration-[250ms] ease-in-out"
                            onError={(e) => {
                              e.target.src = "/images/default-user.png";
                            }}
                          />
                        </div>
                        <ChevronDown className="text-[var(--muted)]" size={16} />
                      </div>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent
                      align="end"
                      sideOffset={15}
                      className="min-w-[220px] bg-secondary border-input rounded-md shadow-[0_25px_50px_rgba(0,0,0,0.6)] p-[0.6rem] animate-popup-in"
                    >
                      <div className="px-[1.2rem] py-[0.8rem] border-b border-border mb-2 flex flex-col">
                        <span className="font-bold text-foreground text-[0.95rem]">
                          {displayName}
                        </span>
                        <span className="text-[0.75rem] text-[var(--muted)] uppercase">
                          Member
                        </span>
                      </div>
                      <DropdownMenuItem
                        className={dropdownItemClass}
                        onClick={() => handleNavClick("account")}
                      >
                        <User size={16} className="opacity-70" /> Account
                      </DropdownMenuItem>
                      <DropdownMenuItem
                        className={dropdownItemClass}
                        onClick={handleImageCapture}
                      >
                        Update Photo
                      </DropdownMenuItem>
                      <DropdownMenuItem
                        className={dropdownItemLogoutClass}
                        onClick={handleLogout}
                      >
                        <LogOut size={16} className="opacity-70" /> Log out
                      </DropdownMenuItem>
                    </DropdownMenuContent>
                  </DropdownMenu>
                </div>
              </div>
            </div>
          </header>

          {/* Content Area */}
          <main className="flex-1 pt-12 pb-8 max-[768px]:py-4">
            <div className="max-w-[1400px] mx-auto px-[4%]">
              {/* In-dashboard nav — replaces the old floating dock. Friends
                  and Groups are combined under one "Groups" tab. */}
              {/* <nav className={styles.dashboardNav}>
                <button
                  className={`${styles.navTab} ${activePage === "home" ? styles.navTabActive : ""}`}
                  onClick={() => handleNavClick("home")}
                >
                  <LayoutDashboard size={18} />
                  Overview
                </button>
                <button
                  className={`${styles.navTab} ${activePage === "groups" ? styles.navTabActive : ""}`}
                  onClick={() => handleNavClick("groups")}
                >
                  <UsersRound size={18} />
                  Groups
                </button>
                <button
                  className={`${styles.navTab} ${activePage === "history" ? styles.navTabActive : ""}`}
                  onClick={() => handleNavClick("history")}
                >
                  <HistoryIcon size={18} />
                  History
                </button>
              </nav> */}
              <div key={activePage} className="animate-flow-fade-in">
                {renderContent()}
              </div>
            </div>
          </main>

          <Footer />
        </div>
      </div>
    </div>
  );
}
